// Process narrative generation request
const narrativeData = $input.first().json;
const { 
  action, // 'scene', 'dialogue', 'description', 'ambiance', 'plot_hook', 'story_arc', 'consequence'
  campaignId,
  sceneContext = {},
  characterContext = {},
  worldContext = {},
  narrativeType, // 'combat', 'exploration', 'social', 'mystery', 'horror', 'comedy', 'drama'
  tone, // 'serious', 'lighthearted', 'tense', 'mysterious', 'epic', 'intimate'
  pacing, // 'slow', 'medium', 'fast', 'urgent'
  perspective, // 'dm', 'player', 'npc', 'omniscient', 'cinematic'
  narrativeParameters = {}
} = narrativeData;

// Validate required fields
if (!action || !campaignId) {
  throw new Error('Missing required fields: action, campaignId');
}

// Prepare narrative generation context
const narrativeContext = {
  action,
  campaignId,
  sceneContext,
  characterContext,
  worldContext,
  narrativeType: narrativeType || 'exploration',
  tone: tone || 'neutral',
  pacing: pacing || 'medium',
  perspective: perspective || 'dm',
  narrativeParameters,
  timestamp: new Date().toISOString(),
  metadata: {
    processedBy: 'narrative-generation-system',
    version: '2.0',
    requestId: `narr_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`
  }
};

return { json: narrativeContext };

// Gather comprehensive narrative context from campaign and world state
const narrativeContext = $input.first().json;
const { campaignId, sceneContext, characterContext, worldContext } = narrativeContext;

// Fetch campaign world state for narrative context
let campaignWorldState = null;
try {
  const worldResponse = await fetch('http://localhost:5678/webhook/world/update', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      action: 'get',
      campaignId
    })
  });

  if (worldResponse.ok) {
    const worldResult = await worldResponse.json();
    campaignWorldState = worldResult.data;
  }
} catch (error) {
  console.error('Failed to fetch world state:', error);
}

// Get active quests for narrative context
let activeQuests = [];
if (campaignWorldState && campaignWorldState.quests) {
  activeQuests = campaignWorldState.quests.filter(quest => 
    ['active', 'in_progress'].includes(quest.status)
  );
}

// Analyze location for scene setting
const locationAnalysis = analyzeLocationContext(sceneContext, campaignWorldState);

// Analyze character relationships and emotional states
const characterAnalysis = analyzeCharacterContext(characterContext, campaignWorldState);

// Analyze world events and timeline context
const worldAnalysis = analyzeWorldContext(worldContext, campaignWorldState);

// Build comprehensive narrative context
const comprehensiveContext = {
  campaignId,

  // Location and environment
  location: locationAnalysis,

  // Character dynamics
  characters: characterAnalysis,

  // World state and events
  world: worldAnalysis,

  // Active story elements
  activeQuests: activeQuests.map(quest => ({
    id: quest.id,
    name: quest.name,
    type: quest.type,
    importance: quest.importance,
    currentObjective: quest.objectives.find(obj => !obj.completed),
    urgency: quest.urgency
  })),

  // Narrative elements
  narrativeElements: {
    currentInGameTime: campaignWorldState?.currentInGameTime || 'Day 1, Morning',
    weather: determineWeather(locationAnalysis, worldAnalysis),
    atmosphere: calculateAtmosphere(locationAnalysis, characterAnalysis, worldAnalysis),
    mood: determineMood(characterAnalysis, worldAnalysis),
    tension: calculateTension(characterAnalysis, worldAnalysis, activeQuests)
  },

  // Story continuity
  continuity: {
    recentEvents: campaignWorldState?.worldEvents?.slice(-5) || [],
    characterMemories: extractCharacterMemories(characterAnalysis),
    locationHistory: getLocationHistory(locationAnalysis, campaignWorldState),
    plotThreads: identifyActivePlotThreads(activeQuests, worldAnalysis)
  },

  // Thematic elements
  themes: identifyActiveThemes(activeQuests, characterAnalysis, worldAnalysis),

  // Environmental storytelling opportunities
  environmentalStorytelling: identifyEnvironmentalStorytellingOpportunities(locationAnalysis, worldAnalysis),

  timestamp: new Date().toISOString()
};

// Helper functions for context analysis
function analyzeLocationContext(sceneContext, worldState) {
  const location = sceneContext.locationId || sceneContext.locationName || 'unknown';

  let locationData = {
    id: location,
    name: location,
    type: 'unknown',
    description: '',
    properties: {},
    discovered: true,
    lastVisited: null
  };

  // Find location in world state
  if (worldState?.locations) {
    const foundLocation = worldState.locations.find(loc => 
      loc.id === location || loc.name === location
    );

    if (foundLocation) {
      locationData = foundLocation;
    }
  }

  // Enhance with scene context
  return {
    ...locationData,
    currentConditions: sceneContext.conditions || {},
    timeOfDay: extractTimeOfDay(sceneContext.timeOfDay),
    weather: sceneContext.weather || 'clear',
    lighting: calculateLighting(locationData, sceneContext.timeOfDay, sceneContext.weather),
    soundscape: generateSoundscape(locationData, sceneContext),
    smellscape: generateSmellscape(locationData, sceneContext),
    visibility: calculateVisibility(locationData, sceneContext.weather, sceneContext.timeOfDay),
    accessibility: determineAccessibility(locationData, sceneContext),
    hazards: identifyHazards(locationData, sceneContext),
    pointsOfInterest: identifyPointsOfInterest(locationData, sceneContext)
  };
}

function analyzeCharacterContext(characterContext, worldState) {
  const characters = [];

  // Add provided characters
  if (characterContext.characters && Array.isArray(characterContext.characters)) {
    characterContext.characters.forEach(char => {
      const charData = {
        id: char.id || char.name,
        name: char.name,
        role: char.role || 'unknown',
        race: char.race || 'unknown',
        class: char.class || 'unknown',
        level: char.level || 1,
        emotionalState: char.emotionalState || 'neutral',
        physicalCondition: char.physicalCondition || 'healthy',
        relationships: char.relationships || {},
        goals: char.goals || [],
        fears: char.fears || [],
        secrets: char.secrets || [],
        equipment: char.equipment || [],
        abilities: char.abilities || [],

        // Dynamic states
        currentMood: calculateCurrentMood(char),
        stressLevel: calculateStressLevel(char),
        fatigueLevel: calculateFatigueLevel(char),
        motivationLevel: calculateMotivationLevel(char),

        // Narrative positioning
        narrativeRole: determineNarrativeRole(char, characterContext),
        importance: determineCharacterImportance(char, characterContext),
        agency: determineCharacterAgency(char, characterContext)
      };

      characters.push(charData);
    });
  }

  // Add NPCs from world state if relevant
  if (worldState?.npcs && characterContext.includeNearbyNPCs !== false) {
    const nearbyNPCs = worldState.npcs.filter(npc => 
      npc.location === characterContext.currentLocation &&
      npc.status === 'alive'
    );

    nearbyNPCs.slice(0, 5).forEach(npc => {
      if (!characters.find(c => c.id === npc.id)) {
        characters.push({
          id: npc.id,
          name: npc.name,
          role: 'npc',
          race: npc.race,
          class: npc.class,
          level: npc.level,
          emotionalState: npc.properties?.mood || 'neutral',
          physicalCondition: 'healthy',
          relationships: npc.relationships || {},
          goals: npc.properties?.goals || [],
          fears: [],
          secrets: npc.properties?.secrets || [],
          equipment: npc.inventory || [],
          abilities: [],

          currentMood: npc.properties?.mood || 'neutral',
          stressLevel: 0.3,
          fatigueLevel: 0.2,
          motivationLevel: 0.6,

          narrativeRole: 'supporting',
          importance: 0.4,
          agency: 0.5
        });
      }
    });
  }

  // Calculate relationship dynamics
  const relationshipDynamics = calculateRelationshipDynamics(characters);

  return {
    characters,
    relationshipDynamics,
    groupCohesion: calculateGroupCohesion(characters),
    conflictPotential: calculateConflictPotential(characters),
    allianceNetwork: buildAllianceNetwork(characters),
    emotionalTone: calculateEmotionalTone(characters)
  };
}

function analyzeWorldContext(worldContext, worldState) {
  return {
    currentEvents: worldState?.worldEvents?.slice(-10) || [],
    timelineProgress: calculateTimelineProgress(worldState),
    majorStorylines: identifyMajorStorylines(worldState),
    worldTension: calculateWorldTension(worldState),
    politicalClimate: analyzePoliticalClimate(worldState),
    economicConditions: analyzeEconomicConditions(worldState),
    socialAtmosphere: analyzeSocialAtmosphere(worldState),
    supernaturalActivity: analyzeSupernaturalActivity(worldState),
    environmentalChanges: identifyEnvironmentalChanges(worldState)
  };
}

function determineWeather(location, world) {
  const baseWeather = ['clear', 'partly_cloudy', 'overcast', 'light_rain', 'heavy_rain', 'fog', 'snow'];
  const seasonalVariations = {
    summer: ['clear', 'partly_cloudy', 'hot'],
    winter: ['snow', 'cold', 'icy'],
    spring: ['light_rain', 'partly_cloudy', 'clear'],
    fall: ['overcast', 'windy', 'cool']
  };

  const season = extractSeason(world.currentInGameTime);
  const seasonWeather = seasonalVariations[season] || baseWeather;

  return seasonWeather[Math.floor(Math.random() * seasonWeather.length)];
}

function calculateAtmosphere(location, characters, world) {
  let atmosphere = {
    tension: 0.3,
    mystery: 0.2,
    wonder: 0.1,
    danger: 0.2,
    peace: 0.3,
    excitement: 0.2
  };

  // Location-based atmosphere adjustments
  if (location.type === 'dungeon') {
    atmosphere.tension += 0.3;
    atmosphere.mystery += 0.2;
    atmosphere.danger += 0.3;
    atmosphere.peace -= 0.2;
  } else if (location.type === 'tavern') {
    atmosphere.peace += 0.2;
    atmosphere.excitement += 0.1;
    atmosphere.tension -= 0.1;
  } else if (location.type === 'forest') {
    atmosphere.mystery += 0.2;
    atmosphere.wonder += 0.1;
  }

  // Character-based atmosphere adjustments
  if (characters.emotionalTone) {
    if (characters.emotionalTone.stress > 0.6) {
      atmosphere.tension += 0.2;
    }
    if (characters.conflictPotential > 0.5) {
      atmosphere.tension += 0.1;
    }
  }

  // World-based atmosphere adjustments
  if (world.worldTension > 0.7) {
    atmosphere.tension += 0.2;
    atmosphere.danger += 0.1;
  }

  // Normalize values
  Object.keys(atmosphere).forEach(key => {
    atmosphere[key] = Math.max(0, Math.min(1, atmosphere[key]));
  });

  return atmosphere;
}

function determineMood(characters, world) {
  const moods = ['neutral', 'hopeful', 'anxious', 'determined', 'confused', 'excited', 'somber'];

  // Base mood on character emotional states
  let moodScore = 0;
  if (characters.characters) {
    characters.characters.forEach(char => {
      if (char.emotionalState === 'happy') moodScore += 1;
      if (char.emotionalState === 'anxious') moodScore -= 1;
      if (char.emotionalState === 'angry') moodScore -= 1;
      if (char.emotionalState === 'determined') moodScore += 1;
    });
  }

  // Adjust for world tension
  if (world.worldTension > 0.6) moodScore -= 1;

  // Select mood based on score
  if (moodScore > 2) return 'hopeful';
  if (moodScore > 0) return 'determined';
  if (moodScore === 0) return 'neutral';
  if (moodScore > -2) return 'anxious';
  return 'somber';
}

function calculateTension(characters, world, quests) {
  let tension = 0.3; // base tension

  // Character tension
  if (characters.conflictPotential > 0.5) tension += 0.2;
  if (characters.emotionalTone?.stress > 0.6) tension += 0.1;

  // World tension
  if (world.worldTension > 0.5) tension += world.worldTension * 0.3;

  // Quest urgency
  if (quests.length > 0) {
    const urgentQuests = quests.filter(q => q.urgency === 'urgent' || q.urgency === 'critical');
    tension += urgentQuests.length * 0.1;
  }

  return Math.min(1, tension);
}

// Additional helper functions
function extractTimeOfDay(timeString) {
  if (!timeString) return 'day';
  const time = timeString.toLowerCase();
  if (time.includes('morning') || time.includes('dawn')) return 'morning';
  if (time.includes('afternoon') || time.includes('noon')) return 'afternoon';
  if (time.includes('evening') || time.includes('dusk')) return 'evening';
  if (time.includes('night') || time.includes('midnight')) return 'night';
  return 'day';
}

function extractSeason(timeString) {
  if (!timeString) return 'spring';
  const time = timeString.toLowerCase();
  if (time.includes('spring')) return 'spring';
  if (time.includes('summer')) return 'summer';
  if (time.includes('fall') || time.includes('autumn')) return 'fall';
  if (time.includes('winter')) return 'winter';
  return 'spring';
}

function calculateLighting(location, timeOfDay, weather) {
  const lightingLevels = {
    morning: {
      clear: 'bright',
      cloudy: 'dim',
      rainy: 'dim'
    },
    afternoon: {
      clear: 'bright',
      cloudy: 'normal',
      rainy: 'dim'
    },
    evening: {
      clear: 'dim',
      cloudy: 'dark',
      rainy: 'very_dark'
    },
    night: {
      clear: 'very_dark',
      cloudy: 'pitch_black',
      rainy: 'pitch_black'
    }
  };

  const weatherKey = weather.includes('rain') ? 'rainy' : 
                    weather.includes('cloud') ? 'cloudy' : 'clear';

  return lightingLevels[timeOfDay]?.[weatherKey] || 'normal';
}

function generateSoundscape(location, sceneContext) {
  const soundscapes = {
    forest: ['birds_chirping', 'leaves_rustling', 'wind_through_trees'],
    dungeon: ['dripping_water', 'distant_echoes', 'creaking_stone'],
    city: ['crowd_noise', 'merchant_calls', 'distant_music'],
    tavern: ['laughter', 'mug_clinking', 'quiet_conversations'],
    battlefield: ['distant_screams', 'metal_clanging', 'wind_whistling']
  };

  const locationSounds = soundscapes[location.type] || ['ambient_noise'];
  const contextualSounds = sceneContext.sounds || [];

  return [...locationSounds, ...contextualSounds];
}

function generateSmellscape(location, sceneContext) {
  const smellscapes = {
    forest: ['damp_earth', 'pine_trees', 'wildflowers'],
    dungeon: ['musty_air', 'stone_dust', 'old_metal'],
    city: ['cooking_foods', 'horse_manure', 'perfumes'],
    tavern: ['ale', 'smoke', 'roasted_meat'],
    battlefield: ['blood', 'smoke', 'death']
  };

  const locationSmells = smellscapes[location.type] || ['neutral_air'];
  const contextualSmells = sceneContext.smells || [];

  return [...locationSmells, ...contextualSmells];
}

function calculateVisibility(location, weather, timeOfDay) {
  let visibility = 'normal';

  // Weather impact
  if (weather.includes('fog') || weather.includes('heavy_rain')) {
    visibility = 'poor';
  } else if (weather.includes('snow')) {
    visibility = 'reduced';
  }

  // Time of day impact
  if (timeOfDay === 'night') {
    visibility = visibility === 'normal' ? 'limited' : 'very_poor';
  }

  // Location impact
  if (location.type === 'dungeon' || location.type === 'cave') {
    visibility = 'dark';
  }

  return visibility;
}

function determineAccessibility(location, sceneContext) {
  const accessibility = {
    movement: 'normal',
    visibility: 'normal',
    noise_level: 'normal',
    privacy: 'public'
  };

  // Location-based adjustments
  if (location.type === 'dungeon') {
    accessibility.movement = 'difficult';
    accessibility.visibility = 'limited';
    accessibility.noise_level = 'echoey';
    accessibility.privacy = 'private';
  } else if (location.type === 'tavern') {
    accessibility.noise_level = 'loud';
    accessibility.privacy = 'semi_private';
  }

  // Scene context adjustments
  if (sceneContext.conditions?.obstructed) {
    accessibility.movement = 'obstructed';
  }

  if (sceneContext.conditions?.hidden) {
    accessibility.privacy = 'hidden';
  }

  return accessibility;
}

function identifyHazards(location, sceneContext) {
  const hazards = [];

  // Location-based hazards
  if (location.type === 'dungeon') {
    hazards.push('traps', 'unstable_structures', 'darkness');
  }

  if (location.type === 'forest') {
    hazards.push('difficult_terrain', 'wild_animals', 'getting_lost');
  }

  // Context-based hazards
  if (sceneContext.conditions?.dangerous) {
    hazards.push('immediate_threat');
  }

  return hazards;
}

function identifyPointsOfInterest(location, sceneContext) {
  const pointsOfInterest = [];

  // Location features
  if (location.properties?.features) {
    pointsOfInterest.push(...location.properties.features);
  }

  // Scene context points
  if (sceneContext.pointsOfInterest) {
    pointsOfInterest.push(...sceneContext.pointsOfInterest);
  }

  // Generate default points based on location type
  const defaultPoints = {
    dungeon: ['ancient_carvings', 'strange_moss', 'unusual_stones'],
    forest: ['ancient_tree', 'clearing', 'stream'],
    city: ['statue', 'fountain', 'unusual_building'],
    tavern: ['fireplace', 'strange_patron', 'hidden_corner']
  };

  if (defaultPoints[location.type]) {
    pointsOfInterest.push(...defaultPoints[location.type]);
  }

  return pointsOfInterest;
}

function calculateCurrentMood(character) {
  const baseMoods = ['neutral', 'curious', 'cautious', 'confident', 'anxious', 'determined'];
  return baseMoods[Math.floor(Math.random() * baseMoods.length)];
}

function calculateStressLevel(character) {
  return Math.random() * 0.8; // 0.0 to 0.8
}

function calculateFatigueLevel(character) {
  return Math.random() * 0.6; // 0.0 to 0.6
}

function calculateMotivationLevel(character) {
  return 0.4 + Math.random() * 0.5; // 0.4 to 0.9
}

function determineNarrativeRole(character, context) {
  if (character.role === 'dm') return 'narrator';
  if (character.role === 'player') return 'protagonist';
  if (character.importance > 0.7) return 'major_character';
  return 'supporting_character';
}

function determineCharacterImportance(character, context) {
  let importance = 0.5;

  if (character.role === 'player') importance += 0.3;
  if (character.level > 5) importance += 0.1;
  if (character.goals?.length > 2) importance += 0.1;

  return Math.min(1, importance);
}

function determineCharacterAgency(character, context) {
  let agency = 0.5;

  if (character.role === 'player') agency += 0.3;
  if (character.motivationLevel > 0.7) agency += 0.2;
  if (character.stressLevel < 0.3) agency += 0.1;

  return Math.min(1, agency);
}

function calculateRelationshipDynamics(characters) {
  const dynamics = [];

  for (let i = 0; i < characters.length; i++) {
    for (let j = i + 1; j < characters.length; j++) {
      const char1 = characters[i];
      const char2 = characters[j];

      dynamics.push({
        character1: char1.id,
        character2: char2.id,
        relationship: determineRelationship(char1, char2),
        tension: calculateRelationshipTension(char1, char2),
        history: generateRelationshipHistory(char1, char2),
        potential: calculateRelationshipPotential(char1, char2)
      });
    }
  }

  return dynamics;
}

function determineRelationship(char1, char2) {
  if (char1.role === char2.role && char1.role === 'player') {
    return 'allies';
  }
  if (char1.faction && char2.faction && char1.faction !== char2.faction) {
    return 'neutral_potential_conflict';
  }
  return 'neutral';
}

function calculateRelationshipTension(char1, char2) {
  let tension = 0.2;

  if (char1.emotionalState === 'angry' || char2.emotionalState === 'angry') {
    tension += 0.3;
  }

  if (char1.goals?.some(goal => char2.fears?.includes(goal))) {
    tension += 0.2;
  }

  return Math.min(1, tension);
}

function generateRelationshipHistory(char1, char2) {
  const histories = ['strangers', 'recent_acquaintances', 'old_friends', 'former_rivals', 'never_met'];
  return histories[Math.floor(Math.random() * histories.length)];
}

function calculateRelationshipPotential(char1, char2) {
  let potential = 0.5;

  if (char1.goals?.some(goal => char2.goals?.includes(goal))) {
    potential += 0.2;
  }

  if (char1.personality?.traits?.some(trait => char2.personality?.compatible_traits?.includes(trait))) {
    potential += 0.1;
  }

  return Math.min(1, potential);
}

function calculateGroupCohesion(characters) {
  if (characters.length < 2) return 1.0;

  let totalTension = 0;
  let relationshipCount = 0;

  characters.characters?.forEach(char1 => {
    characters.characters?.forEach(char2 => {
      if (char1.id !== char2.id) {
        totalTension += calculateRelationshipTension(char1, char2);
        relationshipCount++;
      }
    });
  });

  const averageTension = relationshipCount > 0 ? totalTension / relationshipCount : 0.5;
  return Math.max(0, 1 - averageTension);
}

function calculateConflictPotential(characters) {
  if (!characters.characters) return 0.3;

  let conflictScore = 0;

  characters.characters.forEach(char => {
    if (char.emotionalState === 'angry') conflictScore += 0.3;
    if (char.stressLevel > 0.6) conflictScore += 0.2;
    if (char.secrets?.length > 2) conflictScore += 0.1;
  });

  return Math.min(1, conflictScore / characters.characters.length);
}

function buildAllianceNetwork(characters) {
  const network = {};

  characters.characters?.forEach(char => {
    network[char.id] = {
      allies: [],
      enemies: [],
      neutral: []
    };

    characters.characters?.forEach(otherChar => {
      if (char.id !== otherChar.id) {
        const relationship = determineRelationship(char, otherChar);
        if (relationship.includes('allie')) {
          network[char.id].allies.push(otherChar.id);
        } else if (relationship.includes('conflict') || relationship.includes('enemy')) {
          network[char.id].enemies.push(otherChar.id);
        } else {
          network[char.id].neutral.push(otherChar.id);
        }
      }
    });
  });

  return network;
}

function calculateEmotionalTone(characters) {
  if (!characters.characters) return { stress: 0.3, happiness: 0.5, tension: 0.3 };

  let totalStress = 0;
  let totalHappiness = 0;
  let totalTension = 0;

  characters.characters.forEach(char => {
    totalStress += char.stressLevel || 0.3;
    totalTension += calculateCharacterTension(char);
    totalHappiness += char.emotionalState === 'happy' ? 1 : 0.5;
  });

  const count = characters.characters.length;

  return {
    stress: totalStress / count,
    happiness: totalHappiness / count,
    tension: totalTension / count
  };
}

function calculateCharacterTension(character) {
  let tension = 0.3;

  if (character.emotionalState === 'anxious') tension += 0.3;
  if (character.emotionalState === 'angry') tension += 0.4;
  if (character.fears?.length > 0) tension += character.fears.length * 0.1;

  return Math.min(1, tension);
}

function calculateTimelineProgress(worldState) {
  // Simple timeline progress calculation
  const baseProgress = 0.3;
  const eventProgress = Math.min(0.4, (worldState?.worldEvents?.length || 0) * 0.02);

  return baseProgress + eventProgress;
}

function identifyMajorStorylines(worldState) {
  const storylines = [];

  // Extract from active quests
  if (worldState?.quests) {
    const mainQuests = worldState.quests.filter(q => q.type === 'main' && q.status === 'active');
    mainQuests.forEach(quest => {
      storylines.push({
        name: quest.name,
        type: 'main_quest',
        importance: quest.importance,
        progress: quest.progress || 0
      });
    });
  }

  // Extract from recent world events
  if (worldState?.worldEvents) {
    const majorEvents = worldState.worldEvents.filter(e => e.importance === 'major');
    majorEvents.forEach(event => {
      storylines.push({
        name: event.description,
        type: 'world_event',
        importance: 0.8,
        progress: 0.5
      });
    });
  }

  return storylines;
}

function calculateWorldTension(worldState) {
  let tension = 0.3;

  // Recent conflict events
  if (worldState?.worldEvents) {
    const conflictEvents = worldState.worldEvents.filter(e => 
      e.type.includes('conflict') || e.type.includes('war') || e.type.includes('invasion')
    );
    tension += conflictEvents.length * 0.1;
  }

  // Faction tensions
  if (worldState?.factions) {
    const hostileFactions = worldState.factions.filter(f => 
      f.alignment && (f.alignment.includes('evil') || f.alignment.includes('hostile'))
    );
    tension += hostileFactions.length * 0.05;
  }

  return Math.min(1, tension);
}

function analyzePoliticalClimate(worldState) {
  return {
    stability: calculatePoliticalStability(worldState),
    conflicts: identifyPoliticalConflicts(worldState),
    alliances: identifyPoliticalAlliances(worldState),
    tensions: calculatePoliticalTensions(worldState)
  };
}

function calculatePoliticalStability(worldState) {
  let stability = 0.7;

  if (worldState?.worldEvents) {
    const politicalEvents = worldState.worldEvents.filter(e => 
      e.type.includes('political') || e.type.includes('rebellion') || e.type.includes('coup')
    );
    stability -= politicalEvents.length * 0.1;
  }

  return Math.max(0, stability);
}

function identifyPoliticalConflicts(worldState) {
  const conflicts = [];

  if (worldState?.factions) {
    worldState.factions.forEach(faction => {
      if (faction.relationships) {
        Object.entries(faction.relationships).forEach(([otherFaction, relation]) => {
          if (relation < -30) {
            conflicts.push({
              faction1: faction.name,
              faction2: otherFaction,
              intensity: Math.abs(relation) / 100
            });
          }
        });
      }
    });
  }

  return conflicts;
}

function identifyPoliticalAlliances(worldState) {
  const alliances = [];

  if (worldState?.factions) {
    worldState.factions.forEach(faction => {
      if (faction.relationships) {
        Object.entries(faction.relationships).forEach(([otherFaction, relation]) => {
          if (relation > 50) {
            alliances.push({
              faction1: faction.name,
              faction2: otherFaction,
              strength: relation / 100
            });
          }
        });
      }
    });
  }

  return alliances;
}

function calculatePoliticalTensions(worldState) {
  const conflicts = identifyPoliticalConflicts(worldState);
  const alliances = identifyPoliticalAlliances(worldState);

  const conflictScore = conflicts.reduce((sum, c) => sum + c.intensity, 0);
  const allianceScore = alliances.reduce((sum, a) => sum + a.strength, 0);

  return {
    overall: Math.max(0, Math.min(1, (conflictScore - allianceScore * 0.5) / 2)),
    conflicts,
    alliances
  };
}

function analyzeEconomicConditions(worldState) {
  return {
    prosperity: calculateEconomicProsperity(worldState),
    tradeRoutes: identifyActiveTradeRoutes(worldState),
    resources: identifyResourceAvailability(worldState),
    markets: analyzeMarketConditions(worldState)
  };
}

function calculateEconomicProsperity(worldState) {
  let prosperity = 0.6;

  if (worldState?.worldEvents) {
    const economicEvents = worldState.worldEvents.filter(e => 
      e.type.includes('economic') || e.type.includes('trade') || e.type.includes('famine')
    );

    economicEvents.forEach(event => {
      if (event.type.includes('famine') || event.type.includes('depression')) {
        prosperity -= 0.2;
      } else if (event.type.includes('boom') || event.type.includes('prosperity')) {
        prosperity += 0.2;
      }
    });
  }

  return Math.max(0, Math.min(1, prosperity));
}

function identifyActiveTradeRoutes(worldState) {
  const routes = [];

  if (worldState?.worldBuilding?.economy?.tradeRoutes) {
    routes.push(...worldState.worldBuilding.economy.tradeRoutes);
  }

  return routes;
}

function identifyResourceAvailability(worldState) {
  const resources = {};

  if (worldState?.worldBuilding?.economy?.resources) {
    Object.entries(worldState.worldBuilding.economy.resources).forEach(([resource, availability]) => {
      resources[resource] = {
        availability,
        demand: calculateResourceDemand(resource, worldState),
        price: calculateResourcePrice(resource, availability, worldState)
      };
    });
  }

  return resources;
}

function calculateResourceDemand(resource, worldState) {
  // Simple demand calculation
  const baseDemand = 0.5;
  const recentEvents = worldState?.worldEvents?.slice(-5) || [];

  const relevantEvents = recentEvents.filter(event => 
    event.description?.toLowerCase().includes(resource.toLowerCase())
  );

  return Math.min(1, baseDemand + relevantEvents.length * 0.1);
}

function calculateResourcePrice(resource, availability, worldState) {
  const basePrice = 1.0;
  const scarcity = 1 - availability;
  const demand = calculateResourceDemand(resource, worldState);

  return basePrice * (1 + scarcity) * (1 + demand);
}

function analyzeMarketConditions(worldState) {
  const markets = [];

  if (worldState?.worldBuilding?.economy?.markets) {
    markets.push(...worldState.worldBuilding.economy.markets);
  }

  return markets.map(market => ({
    ...market,
    activity: calculateMarketActivity(market, worldState),
    prices: analyzeMarketPrices(market, worldState)
  }));
}

function calculateMarketActivity(market, worldState) {
  return 0.5 + Math.random() * 0.4; // Random activity level
}

function analyzeMarketPrices(market, worldState) {
  return {
    food: { trend: Math.random() > 0.5 ? 'rising' : 'falling', change: (Math.random() - 0.5) * 0.2 },
    weapons: { trend: Math.random() > 0.5 ? 'rising' : 'falling', change: (Math.random() - 0.5) * 0.15 },
    magic_items: { trend: Math.random() > 0.5 ? 'rising' : 'falling', change: (Math.random() - 0.5) * 0.3 }
  };
}

function analyzeSocialAtmosphere(worldState) {
  return {
    mood: calculateSocialMood(worldState),
    tensions: identifySocialTensions(worldState),
    celebrations: identifyCelebrations(worldState),
    concerns: identifySocialConcerns(worldState)
  };
}

function calculateSocialMood(worldState) {
  let mood = 0.5;

  if (worldState?.worldEvents) {
    const socialEvents = worldState.worldEvents.filter(e => 
      e.type.includes('festival') || e.type.includes('celebration')
    );

    mood += socialEvents.length * 0.1;
  }

  return Math.max(0, Math.min(1, mood));
}

function identifySocialTensions(worldState) {
  const tensions = [];

  if (worldState?.worldEvents) {
    const tensionEvents = worldState.worldEvents.filter(e => 
      e.type.includes('protest') || e.type.includes('riot') || e.type.includes('unrest')
    );

    tensions.push(...tensionEvents.map(event => ({
      description: event.description,
      location: event.location,
      severity: event.importance || 0.5
    })));
  }

  return tensions;
}

function identifyCelebrations(worldState) {
  const celebrations = [];

  if (worldState?.worldEvents) {
    const celebrationEvents = worldState.worldEvents.filter(e => 
      e.type.includes('festival') || e.type.includes('celebration') || e.type.includes('holiday')
    );

    celebrations.push(...celebrationEvents.map(event => ({
      name: event.description,
      location: event.location,
      type: event.type
    })));
  }

  return celebrations;
}

function identifySocialConcerns(worldState) {
  const concerns = [];

  if (worldState?.worldEvents) {
    const concernEvents = worldState.worldEvents.filter(e => 
      e.type.includes('disease') || e.type.includes('famine') || e.type.includes('crime_wave')
    );

    concerns.push(...concernEvents.map(event => ({
      issue: event.description,
      severity: event.importance || 0.5,
      affected_areas: event.location ? [event.location] : []
    })));
  }

  return concerns;
}

function analyzeSupernaturalActivity(worldState) {
  return {
    magicalEnergy: calculateMagicalEnergy(worldState),
    supernaturalEvents: identifySupernaturalEvents(worldState),
    planarActivity: analyzePlanarActivity(worldState),
    divineActivity: analyzeDivineActivity(worldState)
  };
}

function calculateMagicalEnergy(worldState) {
  let energy = 0.3;

  if (worldState?.worldEvents) {
    const magicalEvents = worldState.worldEvents.filter(e => 
      e.type.includes('magical') || e.type.includes('arcane')
    );

    energy += magicalEvents.length * 0.1;
  }

  return Math.min(1, energy);
}

function identifySupernaturalEvents(worldState) {
  const events = [];

  if (worldState?.worldEvents) {
    const supernaturalEvents = worldState.worldEvents.filter(e => 
      e.type.includes('supernatural') || e.type.includes('paranormal') || e.type.includes('haunting')
    );

    events.push(...supernaturalEvents);
  }

  return events;
}

function analyzePlanarActivity(worldState) {
  return {
    activity_level: Math.random() * 0.6, // Random activity level
    active_planes: ['material_plane'], // Default to material plane
    planar_bleeds: []
  };
}

function analyzeDivineActivity(worldState) {
  return {
    intervention_level: Math.random() * 0.4,
    active_deities: [],
    divine_events: []
  };
}

function identifyEnvironmentalChanges(worldState) {
  const changes = [];

  if (worldState?.worldEvents) {
    const environmentalEvents = worldState.worldEvents.filter(e => 
      e.type.includes('environmental') || e.type.includes('natural') || e.type.includes('weather')
    );

    changes.push(...environmentalEvents);
  }

  return changes;
}

function extractCharacterMemories(characterAnalysis) {
  const memories = [];

  characterAnalysis.characters?.forEach(char => {
    if (char.memories) {
      memories.push(...char.memories.map(memory => ({
        character: char.name,
        memory: memory.description || memory,
        importance: memory.importance || 0.5,
        emotional: memory.emotional || false
      })));
    }
  });

  return memories;
}

function getLocationHistory(locationAnalysis, worldState) {
  const history = [];

  if (worldState?.worldEvents) {
    const locationEvents = worldState.worldEvents.filter(e => 
      e.location === locationAnalysis.id || e.location === locationAnalysis.name
    );

    history.push(...locationEvents.map(event => ({
      event: event.description,
      timestamp: event.timestamp,
      type: event.type
    })));
  }

  return history;
}

function identifyActivePlotThreads(quests, worldAnalysis) {
  const threads = [];

  // Extract from quests
  quests.forEach(quest => {
    if (quest.importance > 0.6) {
      threads.push({
        name: quest.name,
        type: 'quest',
        importance: quest.importance,
        status: 'active'
      });
    }
  });

  // Extract from world events
  if (worldAnalysis.currentEvents) {
    worldAnalysis.currentEvents.forEach(event => {
      if (event.importance === 'major') {
        threads.push({
          name: event.description,
          type: 'world_event',
          importance: 0.8,
          status: 'active'
        });
      }
    });
  }

  return threads;
}

function identifyActiveThemes(quests, characterAnalysis, worldAnalysis) {
  const themes = [];

  // Quest-based themes
  quests.forEach(quest => {
    if (quest.tags) {
      quest.tags.forEach(tag => {
        if (!themes.find(t => t.name === tag)) {
          themes.push({
            name: tag,
            strength: quest.importance,
            source: 'quest'
          });
        }
      });
    }
  });

  // Character-based themes
  characterAnalysis.characters?.forEach(char => {
    if (char.goals) {
      char.goals.forEach(goal => {
        const themeName = extractThemeFromGoal(goal);
        if (themeName && !themes.find(t => t.name === themeName)) {
          themes.push({
            name: themeName,
            strength: 0.5,
            source: 'character'
          });
        }
      });
    }
  });

  return themes;
}

function extractThemeFromGoal(goal) {
  const goalLower = goal.toLowerCase();

  if (goalLower.includes('revenge')) return 'revenge';
  if (goalLower.includes('power')) return 'power';
  if (goalLower.includes('knowledge')) return 'knowledge';
  if (goalLower.includes('love')) return 'love';
  if (goalLower.includes('justice')) return 'justice';
  if (goalLower.includes('freedom')) return 'freedom';

  return null;
}

function identifyEnvironmentalStorytellingOpportunities(location, world) {
  const opportunities = [];

  // Location-based storytelling
  if (location.type === 'dungeon') {
    opportunities.push({
      type: 'architectural_storytelling',
      description: 'Ancient carvings tell the story of previous inhabitants',
      trigger: 'investigation',
      importance: 0.6
    });
  }

  if (location.type === 'forest') {
    opportunities.push({
      type: 'natural_storytelling',
      description: 'Unusual tree formations suggest magical influence',
      trigger: 'perception',
      importance: 0.4
    });
  }

  // History-based storytelling
  if (world.recentEvents?.length > 0) {
    world.recentEvents.slice(-3).forEach(event => {
      if (event.location === location.id || event.location === location.name) {
        opportunities.push({
          type: 'historical_storytelling',
          description: `Evidence of recent ${event.type} can be found`,
          trigger: 'investigation',
          importance: event.importance || 0.5
        });
      }
    });
  }

  return opportunities;
}

return { json: comprehensiveContext };

