parameters.jsCode:
// Generate dynamic dialogue based on character personalities and context
const narrativeContext = $input.first().json;
const { contextualData } = narrativeContext;
const { characters, location, narrativeElements, activeQuests } = contextualData;

// Character personality profiles for dialogue generation
const characterProfiles = {};

if (characters && characters.characters) {
  characters.characters.forEach(char => {
    characterProfiles[char.id] = {
      name: char.name,
      race: char.race,
      class: char.class,
      level: char.level,
      emotionalState: char.emotionalState,
      currentMood: char.currentMood,
      stressLevel: char.stressLevel,
      motivationLevel: char.motivationLevel,

      // Personality traits (0.0-1.0)
      personality: {
        aggression: calculateAggression(char),
        friendliness: calculateFriendliness(char),
        curiosity: calculateCuriosity(char),
        caution: calculateCaution(char),
        humor: calculateHumor(char),
        formality: calculateFormality(char),
        intelligence: calculateIntelligence(char),
        wisdom: calculateWisdom(char),
        charisma: calculateCharisma(char),
        honesty: calculateHonesty(char)
      },

      // Speech patterns
      speechPatterns: {
        vocabulary: determineVocabulary(char),
        sentenceStructure: determineSentenceStructure(char),
        accent: determineAccent(char),
        commonPhrases: generateCommonPhrases(char),
        speakingStyle: determineSpeakingStyle(char)
      },

      // Knowledge and expertise
      knowledge: {
        topics: generateKnowledgeTopics(char),
        expertise: determineExpertise(char),
        ignorance: determineIgnorance(char)
      },

      // Relationships and attitudes
      attitudes: {
        towardsOthers: calculateAttitudesTowardsOthers(char, characters.characters),
        towardsCurrentSituation: calculateAttitudeTowardsSituation(char, contextualData),
        towardsAuthority: calculateAttitudeTowardsAuthority(char),
        towardsMagic: calculateAttitudeTowardsMagic(char),
        towardsViolence: calculateAttitudeTowardsViolence(char)
      }
    };
  });
}

// Generate dialogue based on context
const dialogueGeneration = {
  context: contextualData,
  characterProfiles,

  // Scene-based dialogue prompts
  dialoguePrompts: generateDialoguePrompts(contextualData),

  // Conversation dynamics
  conversationDynamics: calculateConversationDynamics(characters),

  // Potential dialogue topics
  conversationTopics: identifyConversationTopics(contextualData),

  // Conflict and resolution opportunities
  dramaticPotential: calculateDramaticPotential(contextualData)
};

// Helper functions for character personality
function calculateAggression(char) {
  let aggression = 0.3;

  if (char.class === 'barbarian' || char.class === 'fighter') aggression += 0.2;
  if (char.emotionalState === 'angry') aggression += 0.3;
  if (char.race === 'orc') aggression += 0.1;
  if (char.currentMood === 'aggressive') aggression += 0.2;

  return Math.min(1, aggression);
}

function calculateFriendliness(char) {
  let friendliness = 0.5;

  if (char.class === 'bard' || char.class === 'cleric') friendliness += 0.2;
  if (char.emotionalState === 'happy') friendliness += 0.2;
  if (char.currentMood === 'friendly') friendliness += 0.3;

  return Math.min(1, friendliness);
}

function calculateCuriosity(char) {
  let curiosity = 0.4;

  if (char.class === 'wizard' || char.class === 'rogue') curiosity += 0.2;
  if (char.currentMood === 'curious') curiosity += 0.3;

  return Math.min(1, curiosity);
}

function calculateCaution(char) {
  let caution = 0.4;

  if (char.stressLevel > 0.6) caution += 0.2;
  if (char.class === 'rogue') caution += 0.1;
  if (char.currentMood === 'cautious') caution += 0.3;

  return Math.min(1, caution);
}

function calculateHumor(char) {
  let humor = 0.3;

  if (char.class === 'bard') humor += 0.3;
  if (char.emotionalState === 'happy') humor += 0.2;

  return Math.min(1, humor);
}

function calculateFormality(char) {
  let formality = 0.4;

  if (char.class === 'paladin' || char.class === 'monk') formality += 0.2;
  if (char.level > 10) formality += 0.1;

  return Math.min(1, formality);
}

function calculateIntelligence(char) {
  let intelligence = 0.5;

  if (char.class === 'wizard' || char.class === 'artificer') intelligence += 0.3;
  if (char.race === 'elf' || char.race === 'gnome') intelligence += 0.1;

  return Math.min(1, intelligence);
}

function calculateWisdom(char) {
  let wisdom = 0.5;

  if (char.class === 'cleric' || char.class === 'druid') wisdom += 0.3;
  if (char.level > 5) wisdom += 0.1;

  return Math.min(1, wisdom);
}

function calculateCharisma(char) {
  let charisma = 0.5;

  if (char.class === 'bard' || char.class === 'sorcerer') charisma += 0.3;
  if (char.emotionalState === 'confident') charisma += 0.2;

  return Math.min(1, charisma);
}

function calculateHonesty(char) {
  let honesty = 0.6;

  if (char.class === 'paladin') honesty += 0.3;
  if (char.currentMood === 'deceptive') honesty -= 0.3;

  return Math.max(0, Math.min(1, honesty));
}

function determineVocabulary(char) {
  const vocabularies = ['simple', 'moderate', 'complex', 'eloquent'];

  let level = 1; // moderate default
  if (calculateIntelligence(char) > 0.7) level = 2;
  if (calculateIntelligence(char) > 0.9) level = 3;
  if (calculateIntelligence(char) < 0.3) level = 0;

  return vocabularies[level];
}

function determineSentenceStructure(char) {
  const structures = ['simple', 'varied', 'complex'];

  let level = 1; // varied default
  if (calculateIntelligence(char) > 0.6) level = 2;
  if (calculateIntelligence(char) < 0.4) level = 0;

  return structures[level];
}

function determineAccent(char) {
  const accents = {
    human: 'regional_common',
    elf: 'melodic',
    dwarf: 'gruff',
    orc: 'guttural',
    halfling: 'cheerful',
    gnome: 'quick',
    dragonborn: 'resonant',
    tiefling: 'seductive'
  };

  return accents[char.race] || 'neutral';
}

function generateCommonPhrases(char) {
  const phrases = {
    barbarian: ['By the ancestors!', 'Honor in battle!', 'Strength above all!'],
    bard: ['A tale for another time!', 'Music soothes the savage beast!', 'Let us make merry!'],
    cleric: ['By the divine!', 'May your path be blessed!', 'Justice will prevail!'],
    druid: ['Nature provides!', 'The balance must be maintained!', 'All life is connected!'],
    fighter: ['For honor!', 'Stand your ground!', 'Victory or death!'],
    monk: ['Inner peace', 'The way is clear', 'Discipline brings strength'],
    paladin: ['For justice!', 'Evil shall not prevail!', 'The light guides us!'],
    ranger: ['The hunt begins!', 'Nature\'s wisdom', 'Track the truth'],
    rogue: ['In shadows we trust', 'Opportunity knocks', 'Silence is golden'],
    sorcerer: ['Magic flows!', 'Power within!', 'The arcane calls!'],
    warlock: ['The pact holds!', 'Dark power rises!', 'Patron\'s will be done!'],
    wizard: ['Knowledge is power!', 'Arcane mysteries!', 'Logic prevails!']
  };

  return phrases[char.class] || ['Interesting...', 'I see.', 'Perhaps...'];
}

function determineSpeakingStyle(char) {
  const styles = ['direct', 'thoughtful', 'dramatic', 'casual', 'formal', 'mysterious'];

  let style = 'thoughtful'; // default

  if (calculateCharisma(char) > 0.7) style = 'dramatic';
  if (calculateFormality(char) > 0.6) style = 'formal';
  if (calculateHumor(char) > 0.6) style = 'casual';
  if (calculateCaution(char) > 0.7) style = 'mysterious';
  if (calculateAggression(char) > 0.6) style = 'direct';

  return style;
}

function generateKnowledgeTopics(char) {
  const topics = [];

  // Class-based knowledge
  const classTopics = {
    wizard: ['arcane theory', 'spellcraft', 'history', 'magical creatures'],
    cleric: ['religion', 'divine magic', 'philosophy', 'ethics'],
    druid: ['nature', 'animals', 'plants', 'elemental forces'],
    ranger: ['tracking', 'survival', 'beasts', 'geography'],
    rogue: ['stealth', 'locks', 'traps', 'urban knowledge'],
    bard: ['history', 'legends', 'music', 'culture'],
    fighter: ['tactics', 'weapons', 'armor', 'military history'],
    paladin: ['law', 'justice', 'nobility', 'military order'],
    monk: ['philosophy', 'meditation', 'unarmed combat', 'discipline'],
    barbarian: ['tribal customs', 'survival', 'intimidation', 'primal rage'],
    sorcerer: ['innate magic', 'bloodlines', 'raw power', 'emotional magic'],
    warlock: ['forbidden knowledge', 'pacts', 'other planes', 'eldritch secrets']
  };

  if (classTopics[char.class]) {
    topics.push(...classTopics[char.class]);
  }

  // Race-based knowledge
  const raceTopics = {
    elf: ['ancient history', 'art', 'poetry', 'longevity'],
    dwarf: ['crafting', 'mining', 'stone', 'clan traditions'],
    human: ['adaptability', 'politics', 'trade', 'innovation'],
    halfling: ['food', 'comfort', 'stealth', 'community'],
    gnome: ['inventions', 'illusions', 'curiosity', 'engineering'],
    orc: ['strength', 'honor', 'tribal warfare', 'survival'],
    dragonborn: ['honor', 'ancestry', 'determination', 'martial pride'],
    tiefling: ['deception', 'persuasion', 'otherness', 'inner conflict']
  };

  if (raceTopics[char.race]) {
    topics.push(...raceTopics[char.race]);
  }

  return topics;
}

function determineExpertise(char) {
  const knowledge = generateKnowledgeTopics(char);
  return knowledge.slice(0, 3); // Top 3 areas of expertise
}

function determineIgnorance(char) {
  const commonKnowledge = ['politics', 'magic', 'religion', 'history', 'nature'];
  const characterKnowledge = generateKnowledgeTopics(char);

  return commonKnowledge.filter(topic => !characterKnowledge.includes(topic));
}

function calculateAttitudesTowardsOthers(char, allCharacters) {
  const attitudes = {};

  allCharacters.forEach(otherChar => {
    if (char.id !== otherChar.id) {
      let attitude = 0.5; // neutral default

      // Adjust based on personalities
      if (calculateFriendliness(char) > 0.6) attitude += 0.2;
      if (calculateAggression(char) > 0.6) attitude -= 0.1;

      // Adjust based on relationship (if available)
      if (char.relationships && char.relationships[otherChar.id]) {
        attitude += char.relationships[otherChar.id] * 0.3;
      }

      attitudes[otherChar.id] = Math.max(0, Math.min(1, attitude));
    }
  });

  return attitudes;
}

function calculateAttitudeTowardsSituation(char, context) {
  let attitude = 0.5;

  // Adjust based on location
  if (location.type === 'dangerous' && calculateCaution(char) > 0.5) {
    attitude -= 0.2;
  }

  // Adjust based on tension
  if (narrativeElements.tension > 0.6) {
    if (calculateAggression(char) > 0.6) {
      attitude += 0.1; // Ready for action
    } else {
      attitude -= 0.1; // Nervous
    }
  }

  // Adjust based on active quests
  if (activeQuests.length > 0) {
    if (calculateMotivationLevel(char) > 0.6) {
      attitude += 0.1; // Focused on objectives
    }
  }

  return Math.max(0, Math.min(1, attitude));
}

function calculateAttitudeTowardsAuthority(char) {
  let attitude = 0.6;

  if (char.class === 'rogue') attitude -= 0.2;
  if (char.class === 'paladin' || char.class === 'monk') attitude += 0.2;
  if (calculateCaution(char) > 0.6) attitude += 0.1;

  return Math.max(0, Math.min(1, attitude));
}

function calculateAttitudeTowardsMagic(char) {
  let attitude = 0.5;

  if (char.class === 'wizard' || char.class === 'sorcerer' || char.class === 'warlock') {
    attitude += 0.3;
  }
  if (char.class === 'cleric' || char.class === 'druid') {
    attitude += 0.2;
  }
  if (char.class === 'fighter' && char.level < 5) {
    attitude -= 0.1; // Might be suspicious of magic
  }

  return Math.max(0, Math.min(1, attitude));
}

function calculateAttitudeTowardsViolence(char) {
  let attitude = 0.4;

  if (char.class === 'barbarian' || char.class === 'fighter' || char.class === 'paladin') {
    attitude += 0.3;
  }
  if (char.class === 'cleric' || char.class === 'monk') {
    attitude += 0.1;
  }
  if (char.class === 'rogue') {
    attitude += 0.2; // Pragmatic about violence
  }

  return Math.max(0, Math.min(1, attitude));
}

function generateDialoguePrompts(context) {
  const prompts = [];

  // Situation-based prompts
  if (narrativeElements.tension > 0.7) {
    prompts.push('The tension is palpable. What does your character say or do?');
  }

  if (activeQuests.length > 0) {
    prompts.push(`How does your character react to the current quest: ${activeQuests[0].name}?`);
  }

  // Location-based prompts
  if (location.type === 'dungeon') {
    prompts.push('The ancient dungeon echoes with unseen presence. What are your character\'s thoughts?');
  }

  // Character dynamic prompts
  if (characters.characters && characters.characters.length > 1) {
    prompts.push('How does your character interact with the others in this situation?');
  }

  return prompts;
}

function calculateConversationDynamics(characters) {
  if (!characters.characters || characters.characters.length < 2) {
    return { type: 'monologue', initiator: null, participants: [] };
  }

  const dynamics = {
    type: 'group_discussion',
    initiator: null,
    participants: characters.characters.map(c => c.id),
    dominantVoices: [],
    quietMembers: [],
    conflicts: [],
    alliances: []
  };

  // Identify likely initiator (most charismatic or aggressive)
  let highestCharisma = 0;
  characters.characters.forEach(char => {
    const charisma = calculateCharisma(char);
    if (charisma > highestCharisma) {
      highestCharisma = charisma;
      dynamics.initiator = char.id;
    }
  });

  // Identify dominant voices
  characters.characters.forEach(char => {
    if (calculateAggression(char) > 0.6 || calculateCharisma(char) > 0.7) {
      dynamics.dominantVoices.push(char.id);
    } else if (calculateCaution(char) > 0.7) {
      dynamics.quietMembers.push(char.id);
    }
  });

  // Identify potential conflicts
  characters.characters.forEach(char1 => {
    characters.characters.forEach(char2 => {
      if (char1.id !== char2.id) {
        const tension = calculateRelationshipTension(char1, char2);
        if (tension > 0.6) {
          dynamics.conflicts.push({
            character1: char1.id,
            character2: char2.id,
            tension: tension
          });
        }
      }
    });
  });

  return dynamics;
}

function identifyConversationTopics(context) {
  const topics = [];

  // Quest-related topics
  activeQuests.forEach(quest => {
    topics.push({
      type: 'quest',
      subject: quest.name,
      importance: quest.importance,
      urgency: quest.urgency,
      likelySpeakers: ['everyone']
    });
  });

  // Location-based topics
  topics.push({
    type: 'location',
    subject: `Current location: ${location.name}`,
    importance: 0.5,
    urgency: 'normal',
    likelySpeakers: ['curious_characters', 'cautious_characters']
  });

  // Situation-based topics
  if (narrativeElements.tension > 0.6) {
    topics.push({
      type: 'tension',
      subject: 'Current tense situation',
      importance: 0.7,
      urgency: 'high',
      likelySpeakers: ['aggressive_characters', 'cautious_characters']
    });
  }

  // Character relationship topics
  if (characters.conflictPotential > 0.5) {
    topics.push({
      type: 'interpersonal',
      subject: 'Group dynamics and relationships',
      importance: 0.6,
      urgency: 'medium',
      likelySpeakers: ['charismatic_characters', 'insightful_characters']
    });
  }

  return topics;
}

function calculateDramaticPotential(context) {
  let potential = {
    overall: 0.5,
    conflict: 0.3,
    revelation: 0.4,
    decision: 0.5,
    emotional: 0.6
  };

  // Adjust based on character conflicts
  if (characters.conflictPotential > 0.6) {
    potential.conflict += 0.3;
    potential.emotional += 0.2;
  }

  // Adjust based on quest urgency
  if (activeQuests.some(q => q.urgency === 'urgent')) {
    potential.decision += 0.3;
    potential.conflict += 0.2;
  }

  // Adjust based on location
  if (location.type === 'dungeon' || location.type === 'dangerous') {
    potential.conflict += 0.2;
    potential.revelation += 0.1;
  }

  // Normalize values
  Object.keys(potential).forEach(key => {
    potential[key] = Math.max(0, Math.min(1, potential[key]));
  });

  // Calculate overall potential
  potential.overall = Object.values(potential).reduce((sum, val, idx) => {
    return idx === 0 ? val : sum + val;
  }, 0) / (Object.keys(potential).length - 1);

  return potential;
}

return { json: dialogueGeneration };

