parameters.jsCode:
// Store generated narrative content and update systems
const narrativeData = $input.first().json;
const { dialogue, contextualData } = narrativeData;

// Prepare narrative data for storage
const narrativeContent = {
  id: `narrative_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
  campaignId: contextualData.campaignId,
  type: 'dialogue_scene',

  // Content data
  content: dialogue,

  // Context metadata
  context: {
    location: contextualData.location.name,
    time: contextualData.narrativeElements.currentInGameTime,
    weather: contextualData.narrativeElements.weather,
    atmosphere: contextualData.narrativeElements.atmosphere,
    mood: contextualData.narrativeElements.mood,
    tension: contextualData.narrativeElements.tension,
    participants: contextualData.characters.characters.map(c => c.name)
  },

  // Narrative metadata
  metadata: {
    generatedAt: new Date().toISOString(),
    generatedBy: 'narrative_generation_system',
    version: '2.0',
    tags: ['dialogue', 'character_interaction', 'story_development'],
    importance: calculateNarrativeImportance(dialogue, contextualData),
    emotionalImpact: calculateEmotionalImpact(dialogue, contextualData),
    plotRelevance: calculatePlotRelevance(dialogue, contextualData)
  },

  // Analytics
  analytics: {
    dialogueLength: dialogue.dialogue?.length || 0,
    characterCount: contextualData.characters.characters?.length || 0,
    emotionalRange: calculateEmotionalRange(dialogue),
    conflictLevel: calculateConflictLevel(dialogue),
    revelationCount: countRevelations(dialogue)
  }
};

// Store in Google Sheets
const sheetData = [
  narrativeContent.id,
  narrativeContent.campaignId,
  narrativeContent.type,
  JSON.stringify(narrativeContent.content),
  JSON.stringify(narrativeContent.context),
  narrativeContent.metadata.importance,
  narrativeContent.metadata.emotionalImpact,
  narrativeContent.metadata.plotRelevance,
  narrativeContent.metadata.generatedAt,
  narrativeContent.metadata.generatedBy,
  JSON.stringify(narrativeContent.metadata.tags),
  JSON.stringify(narrativeContent.analytics)
];

// Update world state with narrative event
const worldUpdate = {
  action: 'update',
  campaignId: contextualData.campaignId,

  // Add narrative event to world timeline
  worldEvents: [
    {
      id: `narrative_event_${narrativeContent.id}`,
      type: 'narrative_moment',
      description: `Important dialogue: ${dialogue.dialogue_scene?.setting_brief || 'Character interaction'}`,
      location: contextualData.location.name,
      importance: narrativeContent.metadata.importance > 0.7 ? 'major' : 'minor',
      relatedCharacters: contextualData.characters.characters.map(c => c.id),
      narrativeType: 'dialogue',
      emotionalImpact: narrativeContent.metadata.emotionalImpact,
      timestamp: narrativeContent.metadata.generatedAt
    }
  ],

  // Update character relationships if significant
  npcChanges: generateCharacterRelationshipUpdates(dialogue, contextualData),

  metadata: {
    narrativeGeneration: {
      narrativeId: narrativeContent.id,
      type: narrativeContent.type,
      importance: narrativeContent.metadata.importance,
      characterCount: narrativeContent.analytics.characterCount
    }
  }
};

// Helper functions for narrative analysis
function calculateNarrativeImportance(dialogue, context) {
  let importance = 0.5;

  // Adjust based on plot relevance
  if (dialogue.narrative_advancement?.plot_points?.length > 0) {
    importance += 0.2;
  }

  // Adjust based on emotional impact
  if (dialogue.character_development) {
    const devCount = Object.keys(dialogue.character_development).length;
    importance += devCount * 0.1;
  }

  // Adjust based on context tension
  if (context.narrativeElements.tension > 0.6) {
    importance += 0.1;
  }

  // Adjust based on active quests
  if (context.activeQuests?.length > 0) {
    importance += 0.1;
  }

  return Math.min(1, importance);
}

function calculateEmotionalImpact(dialogue, context) {
  let impact = 0.4;

  // Analyze dialogue for emotional content
  if (dialogue.dialogue) {
    dialogue.dialogue.forEach(line => {
      const tone = line.tone?.toLowerCase();
      if (tone?.includes('angry') || tone?.includes('fearful') || tone?.includes('ecstatic')) {
        impact += 0.1;
      }
    });
  }

  // Adjust for character emotional states
  if (context.characters.characters) {
    context.characters.characters.forEach(char => {
      if (char.emotionalState !== 'neutral') {
        impact += 0.05;
      }
    });
  }

  return Math.min(1, impact);
}

function calculatePlotRelevance(dialogue, context) {
  let relevance = 0.3;

  // Check for plot advancement
  if (dialogue.narrative_advancement?.plot_points?.length > 0) {
    relevance += 0.3;
  }

  // Check for quest references
  if (dialogue.dialogue) {
    dialogue.dialogue.forEach(line => {
      if (context.activeQuests.some(quest => 
        line.line?.toLowerCase().includes(quest.name.toLowerCase())
      )) {
        relevance += 0.1;
      }
    });
  }

  // Check for decision making
  if (dialogue.narrative_advancement?.decisions_made?.length > 0) {
    relevance += 0.2;
  }

  return Math.min(1, relevance);
}

function calculateEmotionalRange(dialogue) {
  const emotions = new Set();

  if (dialogue.dialogue) {
    dialogue.dialogue.forEach(line => {
      if (line.tone) {
        emotions.add(line.tone.toLowerCase());
      }
    });
  }

  return emotions.size;
}

function calculateConflictLevel(dialogue) {
  let conflictScore = 0;

  if (dialogue.dialogue) {
    dialogue.dialogue.forEach(line => {
      const tone = line.tone?.toLowerCase();
      if (tone?.includes('angry') || tone?.includes('aggressive') || tone?.includes('defensive')) {
        conflictScore += 1;
      }
    });
  }

  return Math.min(1, conflictScore / (dialogue.dialogue?.length || 1));
}

function countRevelations(dialogue) {
  let revelationCount = 0;

  if (dialogue.character_development) {
    Object.values(dialogue.character_development).forEach(development => {
      if (development.revelations && development.revelations.length > 0) {
        revelationCount += development.revelations.length;
      }
    });
  }

  return revelationCount;
}

function generateCharacterRelationshipUpdates(dialogue, context) {
  const updates = [];

  if (dialogue.character_development && context.characters.characters) {
    Object.entries(dialogue.character_development).forEach(([charName, development]) => {
      const char = context.characters.characters.find(c => c.name === charName);
      if (char) {
        // Update emotional state based on dialogue
        if (development.emotional_arc) {
          updates.push({
            npcId: char.id,
            action: 'update',
            data: {
              properties: {
                mood: development.emotional_arc,
                last_conversation: dialogue.dialogue_scene?.setting_brief,
                relationship_changes: development.relationship_changes
              }
            }
          });
        }
      }
    });
  }

  return updates;
}

return { 
  json: {
    narrativeContent,
    sheetData,
    worldUpdate
  } 
};

// Update world state with narrative content
const narrativeData = $input.first().json;
const { worldUpdate } = narrativeData;

// Send world state update
let worldUpdateResult = null;
try {
  const worldResponse = await fetch('http://localhost:5678/webhook/world/update', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(worldUpdate)
  });

  if (worldResponse.ok) {
    worldUpdateResult = await worldResponse.json();
  }
} catch (error) {
  console.error('Failed to update world state with narrative:', error);
}

return { 
  json: {
    narrativeContent: narrativeData.narrativeContent,
    worldUpdateResult
  } 
};

// Broadcast narrative updates to connected systems
const narrativeData = $input.first().json;
const { narrativeContent } = narrativeData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'narrative_generated',
  data: {
    narrativeId: narrativeContent.id,
    campaignId: narrativeContent.campaignId,
    type: narrativeContent.type,
    location: narrativeContent.context.location,
    participants: narrativeContent.context.participants,
    importance: narrativeContent.metadata.importance,
    emotionalImpact: narrativeContent.metadata.emotionalImpact,
    generatedAt: narrativeContent.metadata.generatedAt,
    tags: narrativeContent.metadata.tags
  },
  channels: [
    `campaign_${narrativeContent.campaignId}`,
    'narrative_updates',
    'dm_updates'
  ],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast narrative update:', error);
});

// Send character-specific updates
if (narrativeContent.context.participants) {
  narrativeContent.context.participants.forEach(participantName => {
    const characterNotification = {
      type: 'character_narrative_update',
      data: {
        characterName: participantName,
        narrativeId: narrativeContent.id,
        narrativeType: narrativeContent.type,
        emotionalImpact: narrativeContent.metadata.emotionalImpact,
        location: narrativeContent.context.location
      },
      channels: [`character_${participantName}`, 'character_updates'],
      timestamp: new Date().toISOString()
    };

    fetch('http://localhost:5678/webhook/websocket/broadcast', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(characterNotification)
    }).catch(error => {
      console.error('Failed to send character narrative update:', error);
    });
  });
}

return { json: { broadcast: 'sent', narrativeId: narrativeContent.id, notifications: ['general', 'character_specific'] } };

